def max_value_on_paths(N: int, grid_values: list) -> int:
    """Calculate the maximum sum of values collected on two non-overlapping paths
    in an N x N grid. Each cell value may be collected at most once."""
    # Build the grid
    grid = [[0] * N for _ in range(N)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x - 1][y - 1] = v
    # DP initialization: dp[i1][i2] is max sum when first path at row i1, second at row i2
    NEG_INF = -10**18
    dp = [[NEG_INF] * N for _ in range(N)]
    dp[0][0] = grid[0][0]
    # Total steps from (0,0) to (N-1,N-1) is 2*(N-1)
    for step in range(0, 2 * (N - 1)):
        newdp = [[NEG_INF] * N for _ in range(N)]
        i_min = max(0, step - (N - 1))
        i_max = min(N - 1, step)
        for i1 in range(i_min, i_max + 1):
            j1 = step - i1
            if j1 < 0 or j1 >= N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = step - i2
                if j2 < 0 or j2 >= N:
                    continue
                cur = dp[i1][i2]
                if cur == NEG_INF:
                    continue
                # Move options: down (1,0) or right (0,1)
                for di1, dj1 in (1, 0), (0, 1):
                    ni1 = i1 + di1
                    nj1 = j1 + dj1
                    if ni1 >= N or nj1 >= N:
                        continue
                    for di2, dj2 in (1, 0), (0, 1):
                        ni2 = i2 + di2
                        nj2 = j2 + dj2
                        if ni2 >= N or nj2 >= N:
                            continue
                        add = grid[ni1][nj1]
                        if not (ni1 == ni2 and nj1 == nj2):
                            add += grid[ni2][nj2]
                        total = cur + add
                        if total > newdp[ni1][ni2]:
                            newdp[ni1][ni2] = total
        dp = newdp
    return dp[N - 1][N - 1] if dp[N - 1][N - 1] != NEG_INF else 0

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # contradiction
        else:
            mapping[e_char] = o_char

    # Check that all characters in message have a mapping
    for ch in message:
        if ch not in mapping:
            return "Failed"

    decoded = ''.join(mapping[ch] for ch in message)
    return decoded

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs a binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string. The function assumes
    all node labels are unique characters.

    Raises:
        ValueError: If input strings are of different lengths, contain
                    duplicate characters, or do not represent the same set
                    of nodes.
    """
    if not inorder and not postorder:
        return ""

    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder strings must be of the same length.")

    # Ensure all characters are unique and both strings contain the same set
    if len(set(inorder)) != len(inorder) or len(set(postorder)) != len(postorder):
        raise ValueError("All nodes must have unique labels.")
    if set(inorder) != set(postorder):
        raise ValueError("Inorder and postorder strings must contain the same nodes.")

    # Map from node label to its index in the inorder string for O(1) lookup
    index_map = {char: idx for idx, char in enumerate(inorder)}

    def helper(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start > in_end:
            return ""

        root = postorder[post_end]
        root_idx = index_map.get(root)
        if root_idx is None:
            raise ValueError(f"Node '{root}' not found in inorder traversal.")

        left_count = root_idx - in_start
        right_count = in_end - root_idx

        left_pre = helper(
            in_start, root_idx - 1,
            post_start, post_start + left_count - 1
        )
        right_pre = helper(
            root_idx + 1, in_end,
            post_start + left_count, post_end - 1
        )
        return root + left_pre + right_pre

    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying
    transformation rules recursively using breadth‑first search.

    Args:
        n (int): The original integer.
        rules (list of tuples): Each tuple (x, y) means digit x can be
                                transformed into digit y.

    Returns:
        int: Count of unique numbers reachable from n, including n itself.
    """
    # Build a mapping from source digit to list of possible target digits
    rule_map = {}
    for src, dst in rules:
        try:
            src_digit = int(src)
            dst_digit = int(dst)
        except ValueError:
            continue  # skip invalid rules
        rule_map.setdefault(src_digit, []).append(dst_digit)

    # BFS initialization
    visited = {n}
    queue = [n]
    ptr = 0

    while ptr < len(queue):
        current = queue[ptr]
        ptr += 1
        s = str(current)

        # For each position in the number, try applicable rules
        for idx, ch in enumerate(s):
            digit = int(ch)
            if digit not in rule_map:
                continue
            for replacement in rule_map[digit]:
                # Avoid transforming digit to itself – would create duplicate
                if replacement == digit:
                    continue
                new_s = s[:idx] + str(replacement) + s[idx + 1 :]
                new_num = int(new_s)
                if new_num not in visited:
                    visited.add(new_num)
                    queue.append(new_num)

    return len(visited)

