    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.
    """
    # Helper function to determine truth value of a statement
    def statement_truth(speaker: str, stmt: str) -> bool | None:
        """Return True if the statement is true given the scenario, False if false, or None if unrecognized."""
        stmt_clean = stmt.strip().rstrip('.')
        # If statement mentions a day of the week, ignore it
        for day in days_of_week:
            if day.lower() in stmt_clean.lower():
                return None  # skip this statement

        stmt_upper = stmt_clean.upper()

        # Speaker refers to themselves
